begin;
create table if not exists hq.compliance_risks(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),title text not null,category text not null,description text,likelihood smallint not null check(likelihood between 1 and 5),impact smallint not null check(impact between 1 and 5),risk_score smallint generated always as(likelihood*impact) stored,status text not null default 'identified' check(status in('identified','assessed','mitigating','accepted','closed')),owner_employee_id uuid references hq.employees(id),mitigation_plan text,target_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists hq.compliance_controls(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),risk_id uuid references hq.compliance_risks(id) on delete set null,title text not null,control_type text not null check(control_type in('preventive','detective','corrective')),frequency text,effectiveness text not null default 'untested' check(effectiveness in('untested','ineffective','partial','effective')),owner_employee_id uuid references hq.employees(id),last_tested_on date,next_test_on date,evidence_reference text,created_at timestamptz not null default now());
create table if not exists hq.compliance_incidents(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),title text not null,incident_type text not null,severity text not null check(severity in('low','medium','high','critical')),description text,occurred_at timestamptz not null,status text not null default 'open' check(status in('open','investigating','contained','resolved','closed')),owner_employee_id uuid references hq.employees(id),root_cause text,corrective_action text,resolved_at timestamptz,created_at timestamptz not null default now());
create table if not exists hq.compliance_reviews(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),review_type text not null,title text not null,scope text,starts_on date,ends_on date,due_on date,status text not null default 'planned' check(status in('planned','in_progress','findings_issued','completed','cancelled')),owner_employee_id uuid references hq.employees(id),findings_count integer not null default 0,recommendations text,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['compliance_risks','compliance_controls','compliance_incidents','compliance_reviews'] loop execute format('alter table hq.%I enable row level security',t);execute format('revoke all on hq.%I from public,anon,authenticated',t);execute format('grant all on hq.%I to service_role',t);end loop;end $$;
create index if not exists idx_hq_risk_score on hq.compliance_risks(risk_score desc,status);create index if not exists idx_hq_incident_severity on hq.compliance_incidents(severity,status,occurred_at desc);create index if not exists idx_hq_review_due on hq.compliance_reviews(due_on,status);
commit;
